import { createActionRequester } from '../../types/utils/createActionRequester';
import { UserScriptActionType } from './UserScriptActionType';
import { UserScriptModuleTypes } from './UserScriptModuleTypes';

/**
 * The type declarations of every module this service lets user scripts import that declared
 * `types` (defineUserScriptModule), for a script editor's autocomplete and type checking.
 * Modules without `types` are left out. Generated by the bundler from each module's
 * TypeScript entry, so they always match the code the service runs.
 */
export const askUserScriptModuleTypes = createActionRequester<UserScriptModuleTypes[]>()({
  actionType: UserScriptActionType.ModuleTypes,
  errorTypes: [
    'TypesNotFound', // a declared types entry did not load as declarations (a bundling problem)
  ],
  getPayload: () => undefined,
});
